/// @brief Enumeration for Network Service Discovery DNSSD error code.
/// @since_tizen 3.0
abstract class dnssd_error_e {
  /// < Successful
  static const int DNSSD_ERROR_NONE = 0;

  /// < Out of memory
  static const int DNSSD_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied
  static const int DNSSD_ERROR_PERMISSION_DENIED = -13;

  /// < Invalid operation
  static const int DNSSD_ERROR_INVALID_OPERATION = -38;

  /// < Invalid function parameter
  static const int DNSSD_ERROR_INVALID_PARAMETER = -22;

  /// < Not supported
  static const int DNSSD_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Not Initialized
  static const int DNSSD_ERROR_NOT_INITIALIZED = -30015487;

  /// < Already registered
  static const int DNSSD_ERROR_ALREADY_REGISTERED = -30015486;

  /// < Name conflict
  static const int DNSSD_ERROR_NAME_CONFLICT = -30015485;

  /// < Background daemon not running
  static const int DNSSD_ERROR_SERVICE_NOT_RUNNING = -30015484;

  /// <  Service not found
  static const int DNSSD_ERROR_SERVICE_NOT_FOUND = -30015483;

  /// < Operation failed
  static const int DNSSD_ERROR_OPERATION_FAILED = -30015482;
}

/// @brief Enumeration for Network Service Discovery DNSSD browse state.
/// @since_tizen 3.0
abstract class dnssd_service_state_e {
  /// <Available DNS-SD service found
  static const int DNSSD_SERVICE_STATE_AVAILABLE = 0;

  /// <DNS-SD service not available
  static const int DNSSD_SERVICE_STATE_UNAVAILABLE = 1;

  /// <Lookup failure for service name
  static const int DNSSD_SERVICE_STATE_NAME_LOOKUP_FAILED = 2;

  /// <Lookup failure for host name and port number
  static const int DNSSD_SERVICE_STATE_HOST_NAME_LOOKUP_FAILED = 3;

  /// <Lookup failure for IP address
  static const int DNSSD_SERVICE_STATE_ADDRESS_LOOKUP_FAILED = 4;
}

